-- FinCollect ERP — demo data
-- Every login below uses the password: password
-- Dates are relative to CURDATE(), so the demo always has "today" activity.
USE fincollect;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;















SELECT c.collection_date, c.receipt_no, CONCAT('Collection - ', cu.name), 0, c.collected_amount, 0, 'collection'
FROM collections c JOIN customers cu ON cu.id = c.customer_id
WHERE c.payment_mode = 'cash' AND c.collection_date >= CURDATE() - INTERVAL 60 DAY
ORDER BY c.collection_date, c.collection_time;

SELECT voucher_date, voucher_number, narration, amount, 0, 0, 'expense'
FROM vouchers WHERE payment_mode = 'cash' AND voucher_type IN ('payment','expense') AND approval_status = 'approved';

-- Running balances
SET @bal := 0;
UPDATE cash_transactions SET balance = (@bal := @bal + credit - debit) ORDER BY txn_date, id;

SET @bal := 5000000;
UPDATE bank_transactions SET balance = (@bal := @bal + credit - debit) WHERE account_id = 1 ORDER BY txn_date, id;
SET @bal := 2000000;
UPDATE bank_transactions SET balance = (@bal := @bal + credit - debit) WHERE account_id = 2 ORDER BY txn_date, id;
SET @bal := 1500000;
UPDATE bank_transactions SET balance = (@bal := @bal + credit - debit) WHERE account_id = 3 ORDER BY txn_date, id;
UPDATE bank_accounts a SET current_balance = a.opening_balance +
  COALESCE((SELECT SUM(t.credit - t.debit) FROM bank_transactions t WHERE t.account_id = a.id), 0);



-- Area masters from the customer areas, and agents on some customers
SELECT CONCAT('AREA', LPAD(ROW_NUMBER() OVER (ORDER BY branch_id, area), 3, '0')), area, branch_id
FROM (SELECT DISTINCT branch_id, area FROM customers WHERE area <> '') a;
UPDATE areas a JOIN (SELECT branch_id, MIN(staff_id) AS staff_id FROM customers GROUP BY branch_id) c ON c.branch_id = a.branch_id SET a.staff_id = c.staff_id;
UPDATE customers SET agent_id = branch_id WHERE branch_id <= 3 AND id % 3 = 0;

-- Monthly salaries by role
UPDATE users SET monthly_salary = CASE role WHEN 'md' THEN 150000 WHEN 'admin' THEN 60000 WHEN 'manager' THEN 45000 ELSE 22000 END;


SET FOREIGN_KEY_CHECKS = 1;
